#include <filesystem>
#include <iostream>
int main(int argc, char* argv[]) {
    const std::filesystem::path root = argc > 1 ? argv[1] : ".";
    std::error_code ec;
    std::size_t files = 0, cpp_files = 0;
    for (std::filesystem::directory_iterator it(root, ec), end; !ec && it != end; it.increment(ec)) {
        if (!it->is_regular_file(ec)) { if (ec) break; continue; }
        ++files;
        if (it->path().extension() == ".cpp" || it->path().extension() == ".hpp") ++cpp_files;
    }
    if (ec) { std::cerr << "directory scan failed: " << ec.message() << '\n'; return 1; }
    std::cout << "files=" << files << ", cpp-like=" << cpp_files << '\n';
}
